from scipy.optimize import least_squares
def fitm(f,n,trials=40):
    best=None
    for s in range(trials):
        p0=np.random.randn(n)*0.6
        try:
            r=least_squares(lambda p: f(p)-sigma, p0)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return np.mean((best.x if False else f(best.x)-sigma)**2)/np.var(sigma), np.round(best.x,4)
