def run(k, Tb, Eb):
    cols=[]
    L=np.log(1+k*eps)
    ef={'1':np.ones_like(eps),'e':eps,'L':L,'e2':eps**2,'sq':np.sqrt(eps),'iv':1/eps,'Le':L*eps}
    tf={'1':np.ones_like(T),'T':T,'T2':T**2,'eT':np.exp(0.3*T),'emT':np.exp(-T),'eT2':np.exp(0.3*T)*T}
    names=[]
    for a in Eb:
        for b in Tb:
            cols.append(ef[a]*tf[b]); names.append(a+'*'+b)
    X=np.array(cols).T
    c=np.linalg.lstsq(X,sigma,rcond=None)[0]
    r=X@c-sigma
    return np.mean(r**2)/np.var(sigma), names, c
